from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

app = FastAPI()

counter = 0

def sub_dep():
    global counter
    counter += 1
    return counter

def dep1(sd=Depends(sub_dep)):
    return sd

def dep2(sd=Depends(sub_dep)):
    return sd

@app.get("/")
def read_root(d1=Depends(dep1), d2=Depends(dep2)):
    return {"d1": d1, "d2": d2}

client = TestClient(app)

def test_cache_sub_deps_no_scopes():
    global counter
    counter = 0
    response = client.get("/")
    assert response.status_code == 200
    data = response.json()
    assert data["d1"] == data["d2"]
    assert counter == 1

if __name__ == "__main__":
    test_cache_sub_deps_no_scopes()

